type IsString<T> = T extends string ? true : false;
type A = IsString<'hello'>; // true
type B = IsString<42>; // false

type MyNonNullable<T> = T extends null | undefined ? never : T;
type C = MyNonNullable<string | null>; // string

type MyExclude<T, U> = T extends U ? never : T;
type MyExtract<T, U> = T extends U ? T : never;

type Roles = 'admin' | 'user' | 'guest';
type Staff = MyExtract<Roles, 'admin' | 'user'>; // 'admin' | 'user'
type Public = MyExclude<Roles, 'admin'>; // 'user' | 'guest'

type ApiResponse<T> =
  | { success: true; data: T }
  | { success: false; error: string };

type SuccessData<R> = R extends { success: true; data: infer D } ? D : never;

type UserData = SuccessData<ApiResponse<User>>;
// User

type ErrorOnly<R> = R extends { success: false } ? R : never;

type Dist<T> = T extends string ? 'str' : 'other';
type R1 = Dist<string | number>; // 'str' | 'other'

type NonDist<T> = [T] extends [string] ? 'str' : 'other';
type R2 = NonDist<string | number>; // 'other'
